s=s.replace("const update = (key: string, value: any) => setForm(prev => ({ ...prev, [key]: value })); const save", "const update = (key: string, value: any) => setForm(prev => ({ ...prev, [key]: value })); const uploadImages = async (event: React.ChangeEvent<HTMLInputElement>) => { if (!product || !event.target.files?.length) return; setUploading(true); setMessage(''); try { const signatureResponse = await fetch(`${api}/api/admin/uploads/signature`, { headers: { Authorization: `Bearer ${token}` } }); if (!signatureResponse.ok) throw new Error('Cloudinary is not configured'); const signature = await signatureResponse.json(); for (const file of Array.from(event.target.files)) { const data = new FormData(); data.append('file', file); data.append('api_key', signature.api_key); data.append('timestamp', String(signature.timestamp)); data.append('folder', signature.folder); data.append('signature', signature.signature); const uploaded = await fetch(`https://api.cloudinary.com/v1_1/${signature.cloud_name}/image/upload`, { method: 'POST', body: data }); if (!uploaded.ok) throw new Error('Image upload failed'); const image = await uploaded.json(); await fetch(`${api}/api/admin/products/${product.id}/images`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify({ image_url: image.secure_url, alt_text: product.name, sort_order: 0, is_primary: !product.image_url }) }); } setMessage('Images uploaded successfully.'); } catch (error) { setMessage(error instanceof Error ? error.message : 'Image upload failed.'); } finally { setUploading(false); event.target.value = ''; } }; const save", 1)
